"""Prepare the existing coding workflow; COW and RuntimeLog remain authoritative."""
import hashlib,json,os,re,stat,tempfile
from pathlib import Path
from .run_cli import _config,execute,_source_notice
from .cow_client import CowClient,HTTPTransport,OperationJournal,OperationIndeterminate
PROGRAM="""FLOW coding
REPEAT attempts exhausted=stop max=32 until=verified
EXPAND decide from=current profile=control task=task -> proposed
PLAN freeze against=world from=proposed -> plan
ACT perform plan=plan -> outcome
TRANSFORM advance contract=cow-source input=proposed -> current
TRANSFORM feedback contract=tool-feedback input=outcome -> task
VERIFY check contract=command-evidence-and-finish input=outcome -> verified
END
END
"""
MAX_LAUNCH_BYTES=1024*1024
def _bytes(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()
def build_launch(project,task,connection,*,branch,read_paths=(),edit_paths=(),create_paths=(),test_commands=(),from_branch=None,from_snapshot=None,shell_timeout=120):
    project=Path(project).resolve(strict=True)
    if not project.is_dir():raise ValueError('project must be a directory')
    keys={'endpoint_url','endpoint_pin','model_contract_id','execution_profile_id','eos_tokens'}
    if type(connection) is not dict or set(connection)!=keys:
        raise ValueError('connection needs only endpoint/profile identities and EOS IDs; credentials belong in BW_COW_API_KEY')
    HTTPTransport(connection['endpoint_url'])
    if type(task) is not str or not task.strip() or len(task.encode('utf8'))>262144:raise ValueError('bounded nonempty task text required')
    if type(branch) is not str or not 1<=len(branch)<=128:raise ValueError('bounded branch name required')
    if not test_commands or any(type(c) is not str or not c.strip() for c in test_commands):
        raise ValueError('at least one explicit verification command is required')
    if from_snapshot is not None and from_branch is None:raise ValueError('a snapshot requires its source branch')
    if from_branch is not None and (type(from_branch) is not str or not from_branch):raise ValueError('source branch required')
    if from_snapshot is not None and (type(from_snapshot) is not str or not re.fullmatch('[0-9a-f]{64}',from_snapshot)):raise ValueError('invalid source snapshot')
    cow=dict(connection,branch=branch,mode='ask',bootstrap='coding',grammar_registration='inline')
    fork=None
    if from_branch is not None:
        cow.pop('bootstrap');cow['mode']='append_user'
        fork=dict(source_branch=from_branch,snapshot=from_snapshot)
    config=dict(schema=1,source=str(project),run_id=branch,
        grant=dict(read_paths=sorted(set(read_paths)|set(edit_paths)|set(create_paths)),
                   edit_paths=list(edit_paths),create_paths=list(create_paths),allow_tests=False,allow_shell=True),
        bindings=dict(task=dict(type='Text',value=task)),cow=cow,
        shell=dict(timeout=shell_timeout),
        verification=dict(schema=1,commands=[dict(command=c,disposition='exited',exit_code=0) for c in test_commands]))
    config=_config(_bytes(config).decode())
    return dict(schema=1,program=PROGRAM,config=config,fork=fork)
def _validate(launch):
    if type(launch) is not dict or set(launch)!={'schema','program','config','fork'} or type(launch['schema']) is not int or launch['schema']!=1 or launch['program']!=PROGRAM:
        raise ValueError('unsupported coding launch')
    _config(_bytes(launch['config']).decode())
    fork=launch['fork']
    if fork is not None:
        if (type(fork) is not dict or set(fork)!={'source_branch','snapshot'}
                or type(fork['source_branch']) is not str or not fork['source_branch']
                or type(fork['snapshot']) is not str or not re.fullmatch('[0-9a-f]{64}',fork['snapshot'])
                or launch['config']['cow'].get('mode')!='append_user'
                or 'bootstrap' in launch['config']['cow']):
            raise ValueError('retained launch must pin an exact source snapshot')
    elif launch['config']['cow'].get('bootstrap')!='coding':
        raise ValueError('new coding launch requires its bootstrap')
def _state(state,*,create=False,source=None):
    state=Path(state).absolute()
    if state.is_symlink():raise ValueError('state must be a real owned directory')
    if source is not None and state.resolve().is_relative_to(Path(source).resolve()):
        raise ValueError('run state must be outside the source project')
    if create and not state.exists():state.mkdir(mode=0o700)
    info=state.lstat()
    if not stat.S_ISDIR(info.st_mode) or stat.S_IMODE(info.st_mode)!=0o700 or info.st_uid!=os.getuid():
        raise ValueError('state must be an owned directory with mode0700')
    return state
def save_launch(state,launch):
    import fcntl
    _validate(launch)
    state=_state(state,create=True,source=launch['config']['source'])
    raw=_bytes(dict(launch=launch,sha256=hashlib.sha256(_bytes(launch)).hexdigest()))+b'\n'
    if len(raw)>MAX_LAUNCH_BYTES:raise ValueError('coding launch is too large')
    path=state/'coding-launch.json'
    # Serialize trusted setup publishers; atomic rename leaves one file link
    # even if the process stops before staging cleanup. No workflow lives here.
    lockfd=os.open(state/'.coding-launch.lock',os.O_RDWR|os.O_CREAT|getattr(os,'O_NOFOLLOW',0),0o600)
    with os.fdopen(lockfd,'r+b') as lock:
        info=os.fstat(lock.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or info.st_uid!=os.getuid() or stat.S_IMODE(info.st_mode)!=0o600:
            raise ValueError('invalid coding setup lock')
        fcntl.flock(lock.fileno(),fcntl.LOCK_EX)
        if path.exists() or path.is_symlink():
            if read_launch(state)!=launch:raise ValueError('run setup changed; use a new run state')
            return
        fd,name=tempfile.mkstemp(prefix='.coding-launch-',dir=state);temporary=Path(name)
        try:
            with os.fdopen(fd,'wb') as stream:
                os.fchmod(stream.fileno(),0o600);stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.replace(temporary,path)
            directory=os.open(state,os.O_RDONLY|getattr(os,'O_DIRECTORY',0))
            try:os.fsync(directory)
            finally:os.close(directory)
        finally:
            if temporary.exists():temporary.unlink()
def read_launch(state):
    state=_state(state)
    fd=os.open(state/'coding-launch.json',os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0))
    with os.fdopen(fd,'rb') as stream:
        info=os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or info.st_uid!=os.getuid() or stat.S_IMODE(info.st_mode)!=0o600:
            raise ValueError('coding launch must be a private owned regular file')
        raw=stream.read(MAX_LAUNCH_BYTES+1)
    if len(raw)>MAX_LAUNCH_BYTES:raise ValueError('coding launch is too large')
    envelope=json.loads(raw)
    if type(envelope) is not dict or set(envelope)!={'launch','sha256'} or envelope['sha256']!=hashlib.sha256(_bytes(envelope['launch'])).hexdigest():
        raise ValueError('coding launch integrity check failed')
    _validate(envelope['launch'])
    return envelope['launch']
def _client(state,launch):
    cow=launch['config']['cow']
    return CowClient.http(cow['endpoint_url'],journal=OperationJournal(Path(state)/'cow-operations'),api_key=os.environ.get('BW_COW_API_KEY'),endpoint_pin=cow['endpoint_pin'],notice_handler=_source_notice)
def run_saved(state,*,max_steps=1024):
    if type(max_steps) is not int or max_steps<=0:raise ValueError('finite positive step budget required')
    launch=read_launch(state)
    if launch['fork'] is not None:
        fork=launch['fork'];operation='bw-code-fork-'+hashlib.sha256(_bytes(launch)).hexdigest()[:40]
        # The original pinned source and journal ID survive retries. An uncertain
        # fork remains uncertain; never select a newer head or invent a new ID.
        try:
            _client(state,launch).fork(fork['source_branch'],fork['snapshot'],launch['config']['cow']['branch'],operation)
        except OperationIndeterminate as exc:
            raise OperationIndeterminate('Original fork operation '+operation+' is unresolved; reconcile its original journal intent before continuing') from exc
    return execute('run',launch['program'],_bytes(launch['config']).decode(),state,max_steps=max_steps)
def start(args):
    if type(args.max_steps) is not int or args.max_steps<=0:raise ValueError('finite positive step budget required')
    from .__main__ import _source
    connection=json.loads(_source(args.connection))
    launch=build_launch(args.project,_source(args.task_file),connection,branch=args.branch,
        read_paths=args.read,edit_paths=args.edit,create_paths=args.create,
        test_commands=args.test_command,from_branch=args.from_branch,
        from_snapshot=args.from_snapshot,shell_timeout=args.shell_timeout)
    existing=Path(args.state)/'coding-launch.json'
    if launch['fork'] is not None and launch['fork']['snapshot'] is None:
        if existing.exists():
            prior=read_launch(args.state)
            if prior['fork'] is not None and prior['fork']['source_branch']==args.from_branch:
                launch['fork']['snapshot']=prior['fork']['snapshot']
        if launch['fork']['snapshot'] is None:
            # Read-only selection before publication. The snapshot,not a live
            # branch name,is saved before any mutating setup/inference request.
            launch['fork']['snapshot']=_client(args.state,launch).head(args.from_branch).tip
    save_launch(args.state,launch)
    return run_saved(args.state,max_steps=args.max_steps)

"""CLI bindings for the one Interpreter. JSON here is host configuration only.

No model/tool loop lives here. CLI restart reopens the canonical RuntimeLog and
uses original source bindings; it never rebases a resumed workflow on a new tip.
"""
import hashlib
import json
import os
from pathlib import Path
import stat
import time
from .records import RuntimeLog,Artifact,decode
from .kernel import FrameKernel
from .execution import Executor,Grant
from .tool_registry import ToolRegistry
from .interpreter import Interpreter,Value,AdmissionError,_SUPPORTED
from .cow_client import CowClient,OperationJournal
from .model_dispatch import ModelAdapter
from .language import parse
from .coding_defaults import generation_profile,system_prefix
from .model_inputs import model_content

def _source_notice(event):
    """Display provisional work observations; stdout stays machine-readable."""
    import sys
    kind=event['event']
    field='history_tokens' if kind=='source_recomputation_started' else 'prefix_forward_tokens'
    count=event.get(field)
    shown=str(count) if type(count) is int and count>=0 else 'unknown'
    if kind=='source_recomputation_started':
        message='Recomputing retained context: '+shown+' input positions.'
    elif kind=='source_recomputed':
        message='Recomputed '+shown+' input positions; this request paid the prefix cost.'
    else:
        message='Context recomputation failed: '+json.dumps(event.get('error','unknown'),ensure_ascii=True)
    print('[COW] '+message,file=sys.stderr,flush=True)

def _pairs(items):
    result={}
    for key,value in items:
        if key in result:raise AdmissionError('duplicate host configuration field')
        result[key]=value
    return result

def _browser_config(spec):
    """Admit the host geometry menu once for validation and actual execution."""
    from .browser_capture import BrowserConfig
    required={'executable','width','height','timeout'}
    if (type(spec) is not dict or not required<=set(spec) or set(spec)-required-{'viewports'}
            or type(spec['executable']) is not str):
        raise AdmissionError('closed host browser configuration required')
    menu=()
    if 'viewports' in spec:
        choices=spec['viewports']
        if type(choices) is not dict or not 1<=len(choices)<=8:
            raise AdmissionError('bounded named host viewport mapping required')
        rows=[]
        for name,size in choices.items():
            if type(size) is not list or len(size)!=2:
                raise AdmissionError('viewport geometry must be a two-integer list')
            rows.append((name,*size))
        menu=tuple(rows)
    return BrowserConfig(Path(spec['executable']),spec['width'],spec['height'],spec['timeout'],viewports=menu)

def _shell_config(spec,*,validate_only=False):
    from .terminal import ShellConfig,validate_shell_parameters
    if type(spec) is not dict or 'timeout' not in spec or set(spec)-{'timeout','expected_hostname'}:raise AdmissionError('closed host shell configuration required')
    # Parsing a launch is data validation. The execution path below still
    # admits pinned host binaries before any model work; never trust overflow
    # UID65534 or relax root ownership to make nested configuration tests pass.
    validate_shell_parameters(spec['timeout'],spec.get('expected_hostname'))
    if validate_only:return None
    return ShellConfig(timeout=spec['timeout'],expected_hostname=spec.get('expected_hostname'))

def _config(text):
    try:config=json.loads(text,object_pairs_hook=_pairs,parse_constant=lambda _: (_ for _ in ()).throw(AdmissionError('nonfinite host configuration value')))
    except (ValueError,TypeError) as exc:raise AdmissionError('invalid host configuration') from exc
    required={'schema','source','run_id','grant','bindings'}
    if type(config) is not dict or (not required<=set(config) or set(config)-required-{'cow','profiles','verification','browser','shell','context_pack'}) or type(config['schema']) is not int or config['schema']!=1:
        raise AdmissionError('unsupported host configuration fields/schema; credentials belong in BW_COW_API_KEY')
    if type(config['source']) is not str or not Path(config['source']).is_absolute():raise AdmissionError('absolute source path required')
    if type(config['run_id']) is not str or not config['run_id'] or len(config['run_id'])>128:raise AdmissionError('bounded run ID required')
    grant=config['grant']
    required_grant={'edit_paths','read_paths','create_paths','allow_tests'}
    if (type(grant) is not dict or not required_grant<=set(grant)
            or set(grant)-required_grant-{'capture_paths','interact_paths','asset_paths','allow_shell','mode_paths','mode_mask','output_paths'} or type(grant['allow_tests']) is not bool):
        raise AdmissionError('explicit closed host grant required')
    for name in ('edit_paths','read_paths','create_paths','capture_paths','interact_paths','asset_paths','mode_paths','output_paths'):
        if name not in grant:continue
        if type(grant[name]) is not list or any(type(v) is not str for v in grant[name]):raise AdmissionError('grant paths must be string lists')
    if 'allow_shell' in grant and type(grant['allow_shell']) is not bool:raise AdmissionError('shell grant must be an exact boolean')
    if 'shell' in config:_shell_config(config['shell'],validate_only=True)
    if grant.get('allow_shell',False) and 'shell' not in config:raise AdmissionError('shell grant requires explicit host shell configuration')
    captures=grant.get('capture_paths',[])
    if any(path not in grant['read_paths'] for path in captures):raise AdmissionError('capture paths require explicit read grants')
    if any(path not in captures or path not in grant['read_paths'] for path in grant.get('interact_paths',[])):
        raise AdmissionError('interaction paths require explicit capture and read grants')
    assets=grant.get('asset_paths',[])
    if any(path not in grant['read_paths'] for path in assets):
        raise AdmissionError('assets require explicit read grants')
    # Grant admission owns canonical paths, bounds, duplicates and resource types.
    Grant(tuple(grant['edit_paths']),grant['allow_tests'],
          read_paths=tuple(grant['read_paths']),create_paths=tuple(grant['create_paths']),
          capture_paths=tuple(captures),interact_paths=tuple(grant.get('interact_paths',[])),
          asset_paths=tuple(assets),allow_shell=grant.get('allow_shell',False),mode_paths=tuple(grant.get('mode_paths',[])),mode_mask=grant.get('mode_mask',0),output_paths=tuple(grant.get('output_paths',[])))
    browser=config.get('browser')
    if browser is not None:
        _browser_config(browser)
    if captures and browser is None:raise AdmissionError('capture grants require a host browser configuration')
    if 'profiles' not in config:config['profiles']={'control':generation_profile()}
    if type(config['bindings']) is not dict or type(config['profiles']) is not dict:raise AdmissionError('named bindings/profiles required')
    for name,value in config['bindings'].items():
        if type(value) is not dict or set(value)!={'type','value'} or value['type'] not in ('Text','ToolProposal','ModelInput'):
            raise AdmissionError('CLI initial data must be explicitly typed text/proposal/model-input values')
        if value['type']=='ModelInput':
            if type(value['value']) not in (str,list):raise AdmissionError('typed ModelInput requires text or ordered parts')
            try:model_content(value['value'])
            except ValueError as exc:raise AdmissionError('invalid model input: '+str(exc)) from exc
        elif type(value['value']) is not str:raise AdmissionError('text/proposal value must be text')
    if any(name in config['bindings'] for name in ('world','current','host-config-sha256')):raise AdmissionError('reserved initial binding name')
    cow=config.get('cow')
    if cow is not None:
        keys={'endpoint_url','endpoint_pin','model_contract_id','execution_profile_id','eos_tokens','branch','mode'}
        if type(cow) is not dict or not keys<=set(cow) or set(cow)-keys-{'bootstrap','grammar_registration'} or cow['mode'] not in ('ask','append_user') or any(type(cow[k]) is not str or not cow[k] for k in keys-{'eos_tokens'}):
            raise AdmissionError('explicit closed COW source/profile configuration required')
        if 'bootstrap' in cow and (cow['bootstrap']!='coding' or cow['mode']!='ask'):raise AdmissionError('coding bootstrap requires a new context-only ask boundary')
        if 'grammar_registration' in cow and (cow['grammar_registration']!='inline' or not (cow.get('bootstrap')=='coding' or ('bootstrap' not in cow and cow['mode']=='append_user'))):
            raise AdmissionError('inline grammar registration requires coding bootstrap or explicit user continuation')
        if type(cow['eos_tokens']) is not list or not cow['eos_tokens'] or any(type(t) is not int or t<0 for t in cow['eos_tokens']):raise AdmissionError('actual EOS token IDs required')
    if 'context_pack' in config:
        import re
        pack=config['context_pack']
        if (type(pack) is not dict or set(pack)!={'path','pack_id'}
                or type(pack['path']) is not str or not Path(pack['path']).is_absolute()
                or type(pack['pack_id']) is not str or not re.fullmatch('[0-9a-f]{64}',pack['pack_id'])):
            raise AdmissionError('context_pack requires an absolute path and SHA-256 pack_id pin')
        if cow is None or cow.get('bootstrap')!='coding':
            raise AdmissionError('reference packs require a new coding bootstrap; saved roots stay immutable')
    return config

def execute(command,source,config_text,state,*,max_steps):
    config=_config(config_text)
    nodes=parse(source);pending=list(nodes)
    while pending:
        node=pending.pop()
        if node.opcode not in _SUPPORTED|{'FLOW'}:raise AdmissionError('unsupported execution operation: '+node.opcode)
        pending.extend(node.body)
    state=Path(state).absolute()
    if state.exists() or state.is_symlink():
        info=state.lstat()
        if not stat.S_ISDIR(info.st_mode) or stat.S_IMODE(info.st_mode)!=0o700:raise AdmissionError('state must be an owned real directory with mode0700')
    else:state.mkdir(mode=0o700,parents=False)
    with RuntimeLog(state/'ledger') as log:
        kernel=FrameKernel(log)
        world=state/'world';source_dir=Path(config['source'])
        browser=None
        if 'browser' in config:
            browser=_browser_config(config['browser'])
        shell=_shell_config(config['shell']) if 'shell' in config else None
        if not world.exists():
            if kernel.frames():raise AdmissionError('owned workspace missing; do not recreate under a saved workflow')
            executor=Executor.create(source_dir,world,browser=browser,shell=shell)
        else:
            if world.is_symlink() or not world.is_dir():raise AdmissionError('owned world must be a real directory')
            executor=Executor(source_dir,world,world/'workspace',browser=browser,shell=shell)
        spec=config['grant'];grant=Grant(tuple(spec['edit_paths']),spec['allow_tests'],create_paths=tuple(spec['create_paths']),read_paths=tuple(spec['read_paths']),capture_paths=tuple(spec.get('capture_paths',[])),interact_paths=tuple(spec.get('interact_paths',[])),asset_paths=tuple(spec.get('asset_paths',[])),allow_shell=spec.get('allow_shell',False),mode_paths=tuple(spec.get('mode_paths',[])),mode_mask=spec.get('mode_mask',0),output_paths=tuple(spec.get('output_paths',[])))
        # Candidate tests need their own sandbox even when the trusted CLI is
        # isolated. Reject an unusable execution boundary before any COW call.
        # A completed workflow replays locally without launching a new process.
        frames=kernel.frames()
        if grant.allow_tests and (not frames or kernel.frame('program')['state']!='Closed'):
            executor.check_test_boundary()
        if grant.allow_shell and (not frames or kernel.frame('program')['state']!='Closed'):
            executor.check_shell_boundary()
        registry=ToolRegistry(executor,grant);adapter=None
        bindings={k:Value(v['type'],v['value']) for k,v in config['bindings'].items()}
        # This digest prevents changed source/grants/endpoint/branch declarations
        # being treated as continuation of an already admitted run. No secret.
        canonical=json.dumps(config,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode()
        bindings['host-config-sha256']=Value('Text',hashlib.sha256(canonical).hexdigest())
        if config.get('cow',{}).get('grammar_registration')=='inline' and 'bootstrap' not in config['cow']:
            from .coding_defaults import continuation_input
            task=bindings.get('task')
            if task is None or task.type not in ('Text','ModelInput'):
                raise AdmissionError('coding continuation requires an explicit task input')
            requirements=tuple((row['command'],row['disposition'],row['exit_code'])
                for row in config.get('verification',{}).get('commands',[]))
            bindings['task']=Value(task.type,continuation_input(task.data,registry.model_schema(),command_requirements=requirements))

        if 'cow' in config:
            cow=config['cow'];client=CowClient.http(cow['endpoint_url'],journal=OperationJournal(state/'cow-operations'),api_key=os.environ.get('BW_COW_API_KEY'),endpoint_pin=cow['endpoint_pin'],notice_handler=_source_notice)
            adapter=ModelAdapter(client,run_id=config['run_id'],model_contract_id=cow['model_contract_id'],execution_profile_id=cow['execution_profile_id'],eos_tokens=tuple(cow['eos_tokens']))
            runtime=Interpreter(kernel,registry,adapter=adapter,profiles=config['profiles'],verification=config.get('verification'))
            runtime.preflight(source,{**{name:value.type for name,value in bindings.items()},'world':'World','current':'COWSource'})
            if cow.get('grammar_registration')=='inline':
                # Full pure preflight above must succeed before publishing metadata.
                # This operation is immutable registration,not model execution.
                # A lost acknowledgment replays only the original journaled bytes.
                from .coding_defaults import grammar_registry
                from .cow_client import OperationIndeterminate
                registration_id='bw-grammar-'+hashlib.sha256(canonical+source.encode('utf8')).hexdigest()[:40]
                try:registered=client.register_grammars(grammar_registry(registry),registration_id)
                except OperationIndeterminate:registered=client.replay_original(registration_id)
                adapter=ModelAdapter(client,run_id=config['run_id'],model_contract_id=cow['model_contract_id'],
                    execution_profile_id=cow['execution_profile_id'],eos_tokens=tuple(cow['eos_tokens']),
                    grammar_mapping=registered['states'])
                runtime=Interpreter(kernel,registry,adapter=adapter,profiles=config['profiles'],verification=config.get('verification'))
                runtime.preflight(source,{**{name:value.type for name,value in bindings.items()},'world':'World','current':'COWSource'})
            if kernel.frames():
                root=kernel.frame('program');original=decode(log.read_artifact(Artifact(*root['inputs'])))
                old=original['bindings']['current'];bindings['current']=Value(*old)
            else:
                if cow.get('bootstrap')=='coding':
                    # Context creation uses the existing original-intent journal.
                    # Retrying setup reuses these IDs/bytes; it never overwrites
                    # a foreign branch or reconstructs a saved model context.
                    seed=hashlib.sha256(canonical+source.encode('utf8')).hexdigest()[:40]
                    pack=config.get('context_pack')
                    # Verify recorded-source freshness before any root publication.
                    # Resumed frames above retain their original immutable COW root.
                    prefix=system_prefix(registry.model_schema(),command_output_paths=grant.output_paths,command_requirements=getattr(runtime._file_policy,"commands",()),**({} if pack is None else dict(context_pack=pack['path'],context_pack_id=pack['pack_id'])))
                    namespace=client.create_namespace('BranchWrite coding','bw-ns-'+seed)['namespace_id']
                    prepared=client.load_context(cow['branch'],namespace,[dict(role='system',content=prefix)],'bw-root-'+seed)
                    head=prepared.receipt.branch
                else:head=client.head(cow['branch'])
                bindings['current']=Value('COWSource',dict(head=dict(name=head.name,revision=head.revision,tip=head.tip,root=head.root),mode=cow['mode']))
        if adapter is None:runtime=Interpreter(kernel,registry,profiles=config['profiles'],verification=config.get('verification'))
        runtime.start(source,bindings)
        limit=1 if command=='step' else max_steps
        report=runtime.run(max_steps=limit)
        root=kernel.frame('program')
        result=dict(status=report.status,frame=report.frame,verified=bool(report.value and report.frame=='program' and report.value.get('verified')),state=str(state),result_artifact=None if root['result'] is None else root['result'][0])
        # Return actual immutable capture artifacts from resumed canonical tool
        # results. They remain in the existing ledger, not an export/cache copy.
        artifacts=[]
        for frame,value in runtime._visible_tool_outcomes(root):
            if value['tool'] not in ('capture_page','interact_page') or value['image'] is None:continue
            ref=Artifact(*value['image']);log.read_artifact(ref)
            artifacts.append(dict(media_type='image/png',sha256=ref.sha256,bytes=ref.size_bytes,path=str(log.artifacts/ref.sha256),
                source_path=value['observation'][1],source_sha256=value['observation'][2],tool_frame=frame['id']))
        result['artifacts']=artifacts
        code=0 if result['verified'] else (1 if report.frame=='program' and report.status=='complete' else 3)
        return code,result

"""The owner-thread .bw interpreter, on the existing FrameKernel only.

COW owns native state. ToolRegistry owns grants and frozen effects. This driver
admits dependent work only after its input returns; no transcript or second log.
Advanced language forms remain explicit preflight refusals until implemented.
"""
from dataclasses import dataclass
from hashlib import sha256
from pathlib import Path
import json
import re
from .records import Artifact,encode,decode
from .kernel import CallSpec,ResultContract,TransitionError
from .language import parse,render
from .tool_registry import ToolRegistry,FrozenToolPlan,FileObservation,ToolOutcome
from .tool_dispatch import tool_call,dispatch_tool
from .model_dispatch import model_call,step_model,FrozenModelCall
from . import planning_retry as retry_module
from .cow_client import BranchHead
from .execution import ToolRejected
